import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireFrame Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireFrame/aireframe-v3-4-0.md","filePath":"aireblock-releases/AireFrame/aireframe-v3-4-0.md","lastUpdated":1793188062000}`),a={name:`aireblock-releases/AireFrame/aireframe-v3-4-0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireframe-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireframe-icon.png"> AireFrame Release Notes</span> <a class="header-anchor" href="#aireframe-release-notes" aria-label="Permalink to “AireFrame Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 3.4.0<br><strong>Release Date:</strong> 4th November 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Download Table Widgets as CSV (FRAME-2717)</li><li>Hide the Actions Column on Table Widgets (FRAME-2637)</li><li>Grouped Table Widget Actions (FRAME-2737)</li><li>Manual Tasks in the Portal (FRAME-2739)</li><li>Clearer Organisation Structure Tree (FRAME-2273)</li></ul><h4 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h4><ul><li>Sibling Fields in Subject List Formatting (FRAME-2467)</li><li>Real-Time Subject Search (FRAME-1006)</li><li>Faster Form List When Creating a Form (FRAME-2735)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Upsert Rules Now Update on Configuration Import (FRAME-2657)</li><li>Aggregate Types Preserved on Configuration Import (FRAME-2709)</li><li>Subject List Ordering Kept When Clicking Home (FRAME-2731)</li><li>Microphone Access Restored in Forms (FRAME-2750)</li><li>Multi-Page PDFs on iPad (FRAME-2758)</li><li>Date-Time Filters Now Match Correctly (FRAME-2772)</li><li>&quot;Show Actions&quot; Setting Preserved on Configuration Import (FRAME-2776)</li></ul><h3 id="⚠️-upgrade-notes" tabindex="-1">⚠️ Upgrade Notes <a class="header-anchor" href="#⚠️-upgrade-notes" aria-label="Permalink to “⚠️ Upgrade Notes”">​</a></h3><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><ul><li><strong>CSV download is not switched on automatically.</strong> If you&#39;d like to use it, contact support to have it enabled for your environment. Once it&#39;s enabled, turn it on for each table widget in the widget designer before users will see the Download CSV option.</li></ul></div><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="download-table-widgets-as-csv-frame-2717" tabindex="-1">Download Table Widgets as CSV (FRAME-2717) <a class="header-anchor" href="#download-table-widgets-as-csv-frame-2717" aria-label="Permalink to “Download Table Widgets as CSV (FRAME-2717)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now download the data in a table widget as a CSV file using the new &quot;Download CSV&quot; button on the table. You can download the data for a single subject or for a location (including the locations beneath it), and the file reflects any filters and sorting you have applied to the table. Values appear as they do on screen, and the file records the date and time the data was taken.</p><p>Downloads are prepared in the background, and the notification bell tells you when your file is ready, or if it could not be created. Very large downloads are declined straight away, with a message asking you to narrow down your data. Only the person who requested a download can use it, and only while they still have access to the widget. Download links expire after a few days. Notifications are also now saved, so they are still there after you refresh the page or sign in again.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can take the data from a table away as a spreadsheet, ready to open in Excel or share with colleagues, without copying it out by hand. You can carry on working while larger downloads are prepared.</p></div><h4 id="hide-the-actions-column-on-table-widgets-frame-2637" tabindex="-1">Hide the Actions Column on Table Widgets (FRAME-2637) <a class="header-anchor" href="#hide-the-actions-column-on-table-widgets-frame-2637" aria-label="Permalink to “Hide the Actions Column on Table Widgets (FRAME-2637)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A new &quot;Show actions&quot; option in the table widget designer allows the actions column to be removed from a table. It is on by default for new and existing widgets.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can create cleaner, read-only tables where actions aren&#39;t needed, and those tables load a little faster too.</p></div><h4 id="grouped-table-widget-actions-frame-2737" tabindex="-1">Grouped Table Widget Actions (FRAME-2737) <a class="header-anchor" href="#grouped-table-widget-actions-frame-2737" aria-label="Permalink to “Grouped Table Widget Actions (FRAME-2737)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Where a table widget combines several data sets that each have actions, the actions are now grouped under the name of the data set they belong to, rather than shown as one flat list.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>It&#39;s now easy to see which action relates to which set of data, helping you pick the right one first time.</p></div><h4 id="manual-tasks-in-the-portal-frame-2739" tabindex="-1">Manual Tasks in the Portal (FRAME-2739) <a class="header-anchor" href="#manual-tasks-in-the-portal-frame-2739" aria-label="Permalink to “Manual Tasks in the Portal (FRAME-2739)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Portal users can now complete manual tasks that aren&#39;t forms. Which tasks Portal users see continues to be controlled through dashboards and widgets.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you use the Portal, you can now complete the manual tasks made available to you.</p></div><h4 id="clearer-organisation-structure-tree-frame-2273" tabindex="-1">Clearer Organisation Structure Tree (FRAME-2273) <a class="header-anchor" href="#clearer-organisation-structure-tree-frame-2273" aria-label="Permalink to “Clearer Organisation Structure Tree (FRAME-2273)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The organisation structure tree now shows an expand arrow only where there is something beneath an item.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When browsing your organisation structure, you won&#39;t click to expand an item only to find it has nothing beneath it.</p></div><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><hr><h4 id="sibling-fields-in-subject-list-formatting-frame-2467" tabindex="-1">Sibling Fields in Subject List Formatting (FRAME-2467) <a class="header-anchor" href="#sibling-fields-in-subject-list-formatting-frame-2467" aria-label="Permalink to “Sibling Fields in Subject List Formatting (FRAME-2467)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When formatting a subject list column with Liquid, you can now use other fields from the same row via <code>sibling.&lt;field_key&gt;</code>, with autocomplete, just as in the visualisation designer.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When setting up a subject list, you can format a column using values from other columns in the same row, for example combining a name and an identifier into one display.</p></div><h4 id="real-time-subject-search-frame-1006" tabindex="-1">Real-Time Subject Search (FRAME-1006) <a class="header-anchor" href="#real-time-subject-search-frame-1006" aria-label="Permalink to “Real-Time Subject Search (FRAME-1006)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When searching for a subject, AireFrame now shows a list of matching suggestions as you type, narrowing the results with each character you enter.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can see straight away whether the subject you&#39;re looking for exists and select it from the list, rather than submitting a search and waiting to find out.</p></div><h4 id="faster-form-list-when-creating-a-form-frame-2735" tabindex="-1">Faster Form List When Creating a Form (FRAME-2735) <a class="header-anchor" href="#faster-form-list-when-creating-a-form-frame-2735" aria-label="Permalink to “Faster Form List When Creating a Form (FRAME-2735)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When you create a new form, the list of forms to choose from now appears more quickly.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Starting a new form is quicker, particularly if you have a large number of forms.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="upsert-rules-now-update-on-configuration-import-frame-2657" tabindex="-1">Upsert Rules Now Update on Configuration Import (FRAME-2657) <a class="header-anchor" href="#upsert-rules-now-update-on-configuration-import-frame-2657" aria-label="Permalink to “Upsert Rules Now Update on Configuration Import (FRAME-2657)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where changes to upsert rules (for example, from &quot;Add&quot; to &quot;Replace&quot;) were not applied when importing configuration into another environment.</p></div><h4 id="aggregate-types-preserved-on-configuration-import-frame-2709" tabindex="-1">Aggregate Types Preserved on Configuration Import (FRAME-2709) <a class="header-anchor" href="#aggregate-types-preserved-on-configuration-import-frame-2709" aria-label="Permalink to “Aggregate Types Preserved on Configuration Import (FRAME-2709)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where the Liquid and Array aggregate types were not correctly carried through configuration export and import, which could result in aggregations being lost or changed.</p></div><h4 id="subject-list-ordering-kept-when-clicking-home-frame-2731" tabindex="-1">Subject List Ordering Kept When Clicking Home (FRAME-2731) <a class="header-anchor" href="#subject-list-ordering-kept-when-clicking-home-frame-2731" aria-label="Permalink to “Subject List Ordering Kept When Clicking Home (FRAME-2731)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where clicking the Home button, or the AireFrame logo, reset the subject list ordering and dashboard view, even when the user was already on the home page.</p></div><h4 id="microphone-access-restored-in-forms-frame-2750" tabindex="-1">Microphone Access Restored in Forms (FRAME-2750) <a class="header-anchor" href="#microphone-access-restored-in-forms-frame-2750" aria-label="Permalink to “Microphone Access Restored in Forms (FRAME-2750)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where microphone access was blocked within AireFrame forms, preventing ambient voice from being used. Access now also applies to forms embedded within the page.</p></div><h4 id="multi-page-pdfs-on-ipad-frame-2758" tabindex="-1">Multi-Page PDFs on iPad (FRAME-2758) <a class="header-anchor" href="#multi-page-pdfs-on-ipad-frame-2758" aria-label="Permalink to “Multi-Page PDFs on iPad (FRAME-2758)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where &quot;View as PDF&quot; on iPad only showed the first page with no way to scroll. PDFs on iOS now display in an inline viewer that supports multiple pages, and remain in place rather than opening a new tab.</p></div><h4 id="date-time-filters-now-match-correctly-frame-2772" tabindex="-1">Date-Time Filters Now Match Correctly (FRAME-2772) <a class="header-anchor" href="#date-time-filters-now-match-correctly-frame-2772" aria-label="Permalink to “Date-Time Filters Now Match Correctly (FRAME-2772)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where filtering a subject list date-time column with &quot;=&quot; returned no results. Matching is now based on the selected minute, in line with the precision of the date-time picker.</p></div><h4 id="show-actions-setting-preserved-on-configuration-import-frame-2776" tabindex="-1">&quot;Show Actions&quot; Setting Preserved on Configuration Import (FRAME-2776) <a class="header-anchor" href="#show-actions-setting-preserved-on-configuration-import-frame-2776" aria-label="Permalink to “&quot;Show Actions&quot; Setting Preserved on Configuration Import (FRAME-2776)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where importing configuration exported before version 3.4.0 turned off &quot;Show actions&quot; on every table widget. Missing settings now fall back to their correct defaults, and the same fix applies to two other affected display options.</p></div>`,56)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};